def icon(name):return f'<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{ICONS[name]}</svg>'
def socials():
    links=json.loads((ROOT/'data/social-links.json').read_text(encoding='utf-8'));items=[]
    for name,url in links.items():
        label={'instagram':'Instagram','tiktok':'TikTok','linkedin':'LinkedIn','facebook':'Facebook'}[name]
        if url:items.append(f'<a href="{esc(url)}" target="_blank" rel="noopener noreferrer" aria-label="David Explora on {label}" title="{label}">{icon(name)}<span class="sr-only">{label}</span></a>')
    return '<div class="social-icons" aria-label="David Explora social profiles">'+''.join(items)+'</div>'
def header():
    def group(label,tag,links,wide=False):
        items=''.join(f'<a href="{url}">{esc(text)}<span aria-hidden="true">↗</span></a>' for text,url in links)
        intro={'Safaris':'Compare the northern plains, southern river country and safari–coast connections.','Kilimanjaro':'Choose a mountain route, allow time to prepare and understand the days on the trail.','Zanzibar':'Find the boat trip, forest visit or island stay that fits your coast and dates.','Day trips':'Coffee with local hosts, a forest walk or a day beside the water. Choose your experience and confirm the pickup with David.','Our story':'Meet David and see how your itinerary, arrangements and written quote come together.'}[label]
        return f'<details class="nav-group{(" nav-wide" if wide else "")}"><summary>{label}{icon("arrow")}</summary><div class="nav-panel"><div class="nav-panel-intro"><p class="eyebrow">{tag}</p><p>{intro}</p></div><div class="nav-panel-links">{items}</div></div></details>'
    safari=[('All safari itineraries','packages.html?category=safari'),('Northern circuit','safari.html#northern-circuit'),('Nyerere & Mikumi','southern-safaris.html'),('Great Migration planning','safari.html#migration-planning'),('Private & family journeys','safari.html#private-family'),('Serengeti','serengeti.html'),('Ngorongoro Crater','ngorongoro.html'),('Tarangire','tarangire.html')]
    mountain=[('Mountain overview','kilimanjaro.html'),('8-day Lemosho trek','8-day-lemosho-trek.html'),('7-day Machame trek','7-day-machame-trek.html'),('6-day Marangu trek','6-day-marangu-trek.html'),('Marangu day hike','kilimanjaro-marangu-day-hike.html')]
    coast=[('Island overview & all experiences','zanzibar.html'),('Boat & reef days','zanzibar.html#ocean-days'),('Culture & nature','zanzibar.html#island-life'),('Water sports','zanzibar.html#water-sports'),('Six-day island stay','6-day-zanzibar-island-escape.html'),('Safari + Zanzibar','6-day-drive-in-safari-zanzibar.html')]
    story=[('Meet David','index.html#about'),('How I plan your trip','index.html#travel-with-david'),('Travel seasons','index.html#travel-seasons'),('Booking & confirmation','how-to-book.html')]
    days=[('All local day trips','local-tanzania.html'),('Marangu village & coffee day trip','marangu-village-tour.html'),('Marangu rainforest day hike','kilimanjaro-marangu-day-hike.html'),('Moshi city walk','moshi-city-tour.html'),('Arusha city walk','arusha-city-tour.html'),('Materuni waterfall & coffee','materuni-waterfall-coffee.html'),('Chemka Springs','chemka-springs-day.html')]
    return f'''<header class="site-header"><div class="header-note"><span>Local planning from Moshi &amp; Marangu, Tanzania</span><div class="header-connections">{socials()}<a href="https://wa.me/255778321400" target="_blank" rel="noopener noreferrer">Talk to David ↗</a></div></div><div class="nav-container"><a href="index.html" class="logo" aria-label="David Explora home"><span class="brand-mark" aria-hidden="true">de.</span><span class="brand-name">David <em>Explora</em><small>TANZANIA · WITH LOCAL KNOWLEDGE</small></span></a><button class="menu-toggle" type="button" aria-label="Open navigation" aria-expanded="false" aria-controls="main-navigation">Menu <span aria-hidden="true">☰</span></button><nav class="main-nav" id="main-navigation" aria-label="Main navigation">{group('Safaris','NORTHERN PLAINS · SOUTHERN RIVERS',safari,True)}{group('Kilimanjaro','CHOOSE YOUR MOUNTAIN ROUTE',mountain)}{group('Zanzibar','FIND YOUR ISLAND PACE',coast)}{group('Day trips','A DAY IN DAVID’S HOME REGION',days)}<a href="packages.html">All tours</a>{group('Our story','YOUR LOCAL CONTACT',story)}<a href="index.html#contact" class="nav-cta">Plan your trip ↗</a></nav></div></header>'''
def footer():
 return f'''<footer class="site-footer"><div class="footer-container"><div class="footer-brand"><a class="footer-wordmark" href="index.html">David <em>Explora</em></a><p>Tanzania, with local knowledge.</p><p>Mountain routes, wildlife journeys and island days, connected with care.</p><span class="footer-location">Moshi &amp; Marangu, Tanzania</span>{socials()}</div><div><h2>EXPLORE</h2><a href="safari.html">Northern Tanzania safaris</a><a href="southern-safaris.html">Nyerere &amp; Mikumi</a><a href="kilimanjaro.html">Kilimanjaro treks</a><a href="zanzibar.html">Zanzibar experiences</a><a href="local-tanzania.html">Local day trips</a><a href="packages.html">All tours &amp; saved shortlist</a></div><div><h2>PLAN WITH DAVID</h2><a href="https://wa.me/255778321400" target="_blank" rel="noopener noreferrer">WhatsApp: +255 778 321 400</a><a href="mailto:davidlyamuya819@gmail.com">davidlyamuya819@gmail.com</a><a href="travel-guide.html">Tanzania planning guide</a><a href="explore-tanzania.html">Destination map</a><a href="how-to-book.html">How to book</a><a href="index.html#travel-seasons">Find your travel season</a></div></div><div class="footer-bottom"><p>© <span id="current-year">2026</span> David Explora</p><div><a href="terms.html">Booking terms</a><a href="privacy.html">Privacy</a><a href="photo-credits.html">Photo &amp; film credits</a></div></div></footer>'''
def update_home_source(path):
    text=path.read_text(encoding='utf-8');text=re.sub(r'<header class="site-header">.*?</header>',lambda _:header(),text,flags=re.S);text=re.sub(r'<footer class="site-footer">.*?</footer>',lambda _:footer(),text,flags=re.S)
    if 'rel="preload" href="media/serengeti-lion-cubs-poster.webp"' not in text:text=text.replace('</head>','<link rel="preload" href="media/serengeti-lion-cubs-poster.webp" as="image"></head>')
    text=text.replace('<script src="ui.js" defer></script>','<script src="ui.js" defer></script><script src="features.js" defer></script>') if 'src="features.js"' not in text else text
    if '<!-- BEGIN: homepage-features -->' not in text:text=text.replace('<section class="section travel-preparation">','<!-- BEGIN: homepage-features --><!-- END: homepage-features -->\n<section class="section travel-preparation">')
    text=re.sub(r'"sameAs":\[.*?\]',lambda _: '"sameAs":'+json.dumps([u for u in json.loads((ROOT/'data/social-links.json').read_text(encoding='utf-8')).values() if u]),text)
    text=text.replace('<button type="button" data-rail-next aria-label="Show next tours">→</button></div>', '<button type="button" data-rail-next aria-label="Show next tours">→</button><button type="button" data-rail-pause aria-pressed="false">Pause tours</button></div>')
    path.write_text(text, encoding='utf-8')
def marangu_daytrip(site):
    tour=next(t for t in site.TOURS if t['id']=='marangu-village-tour')
    photos=sorted(tour['gallery'],key=lambda photo:photo['image']!='images/stories/coffee-cherries.webp')
    frames=[]
    for i,photo in enumerate(photos):
        frames.append(f'<figure data-slide class="{("is-active" if i==0 else "")}" aria-hidden="{str(i!=0).lower()}"{(" inert" if i else "")}>{site.img(photo["image"],photo["alt"],False,"(max-width: 800px) 90vw, 50vw")}<figcaption>{esc(photo["caption"])}</figcaption></figure>')
    gallery=f'<div class="marangu-story-gallery tour-photo-gallery" data-carousel role="region" aria-roledescription="carousel" aria-label="Marangu village and coffee photographs"><div class="tour-gallery-frames">{"".join(frames)}</div><p class="gallery-caption" data-visible-caption>{esc(photos[0]["caption"])}</p>{site.controls(len(frames))}</div>'
    return f'''<div class="marangu-day-story">{gallery}<div class="marangu-story-copy"><p class="eyebrow">A DAY IN MY HOME REGION</p><h2>Marangu.<br>Village paths, coffee<br>&amp; Chagga hospitality.</h2><p>Take a day out from Moshi and get to know life in the Kilimanjaro foothills. Walk with local hosts, follow coffee from the plant to the cup, then sit down for a local lunch.</p><dl class="marangu-day-facts"><div><dt>Time</dt><dd>6–7 hours</dd></div><div><dt>Pickup</dt><dd>Moshi hotel</dd></div><div><dt>Style</dt><dd>Private day trip</dd></div></dl><ol class="marangu-day-route"><li><span>01</span>Village &amp; farming walk</li><li><span>02</span>Coffee preparation &amp; tasting</li><li><span>03</span>Local lunch &amp; return to Moshi</li></ol><p class="marangu-day-price"><strong>{site.money(tour['price'])}</strong> / adult <span>Estimate for 2 adults travelling together · includes return Moshi transport, agreed host fees, coffee activity and lunch.</span></p><div class="hero-buttons"><a class="btn btn-primary" href="marangu-village-tour.html">See the Marangu day trip ↗</a><a class="text-link" href="index.html?package=marangu-village-tour#contact">Ask David about my dates ↗</a></div><p class="photo-note">Waterfalls, caves and museums can be added to your written quote. Looking for a mountain walk? <a href="kilimanjaro-marangu-day-hike.html">Choose the separate Marangu rainforest day hike</a>.</p><p class="photo-note">Village destination photos and David’s supplied coffee photos. <a href="photo-credits.html">Sources &amp; credits</a>.</p></div></div>'''

def operator_hero(site):
    scenes=[('media/serengeti-lion-cubs-poster.webp','Lion cubs resting on a Serengeti kopje','SERENGETI / WILDLIFE ON THE KOPJES','Safari','media/serengeti-lion-cubs.mp4',12),('media/kilimanjaro-poster.webp','Kilimanjaro above green forest foothills','KILIMANJARO / FOREST TO HIGH SUMMITS','Kilimanjaro','media/kilimanjaro-background.mp4',10),('media/zanzibar-poster.webp','Boats on turquoise water along the Zanzibar coast','ZANZIBAR / TIME BY THE INDIAN OCEAN','Zanzibar','media/zanzibar-background.mp4',10),('images/stories/coffee-cherries.webp','Green and ripening coffee cherries in a photograph supplied by David Explora','MARANGU / COFFEE & VILLAGE LIFE','Local life',None,7)]
    frames=[]
    for i,(path,alt,caption,label,film,seconds) in enumerate(scenes):
        picture=f'<video data-motion-video data-src="{film}" poster="{path}" muted loop playsinline preload="none" disablepictureinpicture aria-hidden="true" tabindex="-1"><p>{alt}</p></video>' if film else site.img(path,alt,False,'100vw')
        frames.append(f'<figure data-slide data-scene-seconds="{seconds}" class="{("is-active" if i==0 else "")}" aria-hidden="{str(i!=0).lower()}"{(" inert" if i else "")}>{picture}<figcaption>{caption}</figcaption></figure>')
    chapters=''.join(f'<button type="button" data-slide-to="{i}" aria-label="Show {s[3]} scene" aria-pressed="{str(i==0).lower()}"><span>{i+1:02}</span>{s[3]}</button>' for i,s in enumerate(scenes))
    options=[('Safari','safari','Safari'),('Kilimanjaro','mountain','Mountain'),('Zanzibar','coast','Island'),('Local Tanzania','local','Local life')]
    choices=''.join(f'<label for="quick-interest-{i}"><input id="quick-interest-{i}" name="quick-interest" type="radio" value="{value}"{(" checked" if i==0 else "")}><span>{icon(ico)}<span>{label}</span></span></label>' for i,(value,ico,label) in enumerate(options))
    quick=f'''<form class="hero-quick-plan" id="quick-plan-form" action="index.html#contact" method="get"><p class="eyebrow">A FEW DETAILS TO START</p><h2>What brings you<br>to Tanzania?</h2><fieldset class="quick-interests"><legend class="sr-only">Your main travel interest</legend>{choices}</fieldset><div class="quick-fields"><div><label for="quick-date">Arrival date <span>(optional)</span></label><input type="date" id="quick-date" name="quick-date"></div><div><label for="quick-travelers">Travellers</label><input type="number" id="quick-travelers" name="quick-travelers" min="1" max="50" step="1" value="2" required></div></div><button class="btn btn-primary" type="submit">Start my trip request ↗</button><p class="quick-plan-note">Review your full request before sending it to David.</p><p id="quick-plan-status" role="status"></p><noscript><p><a href="index.html#contact">Complete the trip request below</a>.</p></noscript></form>'''
    return f'''<section id="home" class="hero cinema-hero operator-hero" data-carousel data-background-story="true" role="region" aria-roledescription="carousel" aria-label="Tanzania destination films and photographs"><div class="hero-frames">{''.join(frames)}</div><div class="hero-overlay"></div><div class="hero-content hero-layout"><div class="hero-introduction"><p class="hero-eyebrow">KILIMANJARO · SAFARI · ZANZIBAR</p><h1>Your Tanzania.<span>Planned with David.</span></h1><p class="hero-text">The mountain, the wildlife, the coast—and the details that connect them. Choose your experience. I’ll help shape a route around your dates, budget and pace.</p><div class="hero-buttons"><a class="btn btn-primary" href="packages.html">Explore the tours ↗</a><a class="btn btn-secondary" href="#about">Meet your local guide</a></div><div class="hero-trust"><span>Local knowledge</span><span>Private &amp; small groups</span><span>Clear written quotes</span></div></div>{quick}</div><div class="hero-gallery-footer"><p class="hero-scene-caption" data-visible-caption>{scenes[0][2]}</p><div class="story-controls" hidden><div class="hero-chapters">{chapters}</div><div class="hero-playback"><button type="button" data-prev aria-label="Previous destination scene">←</button><span class="story-count" data-counter aria-hidden="true">01 / 04</span><button type="button" data-next aria-label="Next destination scene">→</button><button type="button" data-pause aria-pressed="false">Pause story</button></div></div></div><p class="sr-only" data-announcement aria-live="polite" aria-atomic="true"></p></section>'''
def home_sections(site):
    return f'''<section class="section planning-promise" id="travel-with-david"><div class="section-heading split-heading"><div><p class="eyebrow">A LOCAL CONTACT. A READABLE PLAN.</p><h2>Good journeys start<br>with the practical details.</h2></div><p>Your dates, actual party and preferred pace come first. I connect the experiences, then make the services and costs clear before you decide.</p></div><div class="promise-grid"><article><span>01</span><h3>A route that works</h3><p>Allow time for park drives, mountain preparation and island connections. Departure points and travel days are part of the plan.</p></article><article><span>02</span><h3>Know what you’re paying for</h3><p>Review named accommodation, activities, transport and fees in one written quote, with extras and booking terms stated.</p></article><article><span>03</span><h3>Respect the people and places</h3><p>Agree community visits with hosts, respect photography preferences and give wildlife space. Your guide and local conditions shape the day.</p></article></div></section><section class="section marangu-feature" id="marangu-daytrip">{marangu_daytrip(site)}</section><section class="section season-journal" id="travel-seasons"><figure>{site.img('images/safari-expansion/serengeti-plains.webp','Serengeti river landscape in golden light')}<figcaption>Serengeti landscape · photographed by Stefan Swanepoel</figcaption></figure><div><p class="eyebrow">THE SEASON IS PART OF THE STORY</p><h2>Choose your dates<br>with the landscape in mind.</h2><div class="season-notes"><article><p>Jun–Oct</p><div><h3>Drier safari months</h3><p>Water sources and road access shape the wildlife day. Northern river-crossing plans need location-specific advice; crossings cannot be promised.</p></div></article><article><p>Jan–Feb</p><div><h3>Southern plains &amp; calving</h3><p>Consider the southern Serengeti/Ndutu region for a seasonal itinerary. Exact wildlife movements follow rainfall, not a fixed calendar.</p></div></article><article><p>Mar–May</p><div><h3>Green landscapes &amp; rain</h3><p>Expect greener scenery and changing road conditions. Check camp availability and keep island boat plans flexible.</p></div></article><article><p>Nov–Dec</p><div><h3>Short rains &amp; changing light</h3><p>Build a route that leaves room for weather and local advice. These months can offer varied landscapes and birdlife.</p></div></article></div><a class="text-link" href="travel-guide.html#seasons">Read the seasonal planning guide ↗</a><p class="photo-note">General planning guidance, not a forecast or a wildlife guarantee. <a href="https://www.tanzaniaparks.go.tz/plan-a-trip">TANAPA planning information</a>.</p></div></section>'''
